// Presentis returns dates as yyyyMMdd
function convertDate(value) {
    let returnValue = null;

    if (typeof value !== 'undefined' && value) {
        const dateString = String(value);

        if (dateString.length === 8 && dateString !== '00000000') {
            const date = new Date(dateString.substring(0, 4) + '-' + dateString.substring(4, 6) + '-' + dateString.substring(6, 8));

            if (!isNaN(date)) {
                returnValue = date;
            }
        }
    }

    return returnValue;
}

function getValue() {
    let returnValue = null;

    switch (sourceContract.ContractType) {
        case 'inschrijving': {
            returnValue = convertDate(sourceContract.uitschrijfdatum);
            break;
        }
        default: {
            returnValue = convertDate(sourceContract.einddatum);
            break;
        }
    }

    return returnValue;
}

