function getValue() {
    let returnValue = null;

    switch (sourceContract.ContractType) {
        case 'klas': {
            // Fall back on the klas code when the klas has no description
            if (typeof sourceContract.klas_omschrijving !== 'undefined' && sourceContract.klas_omschrijving) {
                returnValue = sourceContract.klas_omschrijving;
            }
            else {
                returnValue = sourceContract.klas;
            }
            break;
        }
        case 'cursus': {
            // Fall back on the cursus id when the cursus has no description
            if (typeof sourceContract.cursus_omschrijving !== 'undefined' && sourceContract.cursus_omschrijving) {
                returnValue = sourceContract.cursus_omschrijving;
            }
            else {
                returnValue = sourceContract.cursusid;
            }
            break;
        }
        default: {
            returnValue = 'Leerling';
            break;
        }
    }

    return returnValue;
}

